$csv="E:\TTQS\_github_sync_0064\docs\ttqs-quality-20261016\quality-review\0077_R01\inputs\REFLECTION_SYNTHETIC_DATA_0077_R01.csv"
$body=[System.IO.File]::ReadAllText($f)
$rows=Import-Csv $csv
