}
"mismatches=$bad"
"--- theme counts from CSV ---"
$rows | Group-Object primary_theme_code | Sort-Object Name | ForEach-Object { "{0} = {1}  pct={2:N2}%" -f $_.Name,$_.Count,(100*$_.Count/$rows.Count) }

